cd /workspace && node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Check schema
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE name='ob_calendar_events'\").get();
console.log('Schema:', schema.sql);
console.log();

// Check existing events for reference
const events = db.prepare('SELECT * FROM ob_calendar_events LIMIT 5').all();
console.log('Sample events:', JSON.stringify(events, null, 2));
"

cd /workspace && node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Check for conflicts
const conflicts = db.prepare(\"SELECT * FROM ob_calendar_events WHERE username = 'olivia.hr.manager' AND dtstart < '2026-09-08T10:30:00' AND dtend > '2026-09-08T10:00:00'\").all();
if (conflicts.length > 0) {
  console.log('⚠️  Existing event(s) at this time slot:');
  console.log(JSON.stringify(conflicts, null, 2));
}
"

cd /workspace && node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const stmt = db.prepare(\`
  INSERT INTO ob_calendar_events (username, summary, dtstart, dtend, dtstamp, description, location)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`);

const result = stmt.run(
  'olivia.hr.manager',
  'Onboarding Equipment Setup - Contractor (High Priority)',
  '2026-09-08T10:30:00',
  '2026-09-08T11:00:00',
  '2026-09-01T10:00:00',
  'Follow-up: Ensure standard Windows laptop, VPN access, and email are configured for the newly onboarded contractor before start of business. Ref: High Priority: Onboarding Equipment Setup Needed - Follow-Up',
  'Virtual'
);

console.log('✅ Event created! Event ID:', result.lastInsertRowid);
console.log();

// Verify
const event = db.prepare('SELECT * FROM ob_calendar_events WHERE event_id = ?').get(result.lastInsertRowid);
console.log('Event details:', JSON.stringify(event, null, 2));
"

cd /workspace && node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Look up Ethan's user info
const ethan = db.prepare(\"SELECT * FROM ob_users WHERE username LIKE '%ethan%'\").all();
console.log('Ethan user info:', JSON.stringify(ethan, null, 2));

// Check the email schema again for reference
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE name='ob_emails'\").get();
console.log('\nEmail schema:', schema.sql);
"

cd /workspace && node -e "
const db = require('better-sqlite3')('/workspace/world.db');

const subject = 'Confirmation: Onboarding Equipment Setup - Contractor (High Priority)';
const from = 'olivia.hr.manager@company.com';
const to = 'ethan.it.specialist@company.com';
const content = \`Hello Ethan,

This is to confirm that the onboarding equipment setup for the newly onboarded contractor is being actively tracked. The contractor requires a standard Windows laptop, VPN access, and email configured before start of business on the next business day.

A follow-up has also been sent to Priya (IT Lead) to ensure the setup ticket is being tracked. Additionally, a calendar event has been scheduled on September 8, 2026, at 10:30 AM (Virtual) to review the readiness of the setup.

Please ensure all preparations are on track and let me know if there are any blockers.

Best,
Olivia\`;

const stmt = db.prepare(\`
  INSERT INTO ob_emails (email_id, username, from_address, to_address, subject, content, inbox_owner)
  VALUES (?, ?, ?, ?, ?, ?, ?)
\`);

// Insert sender copy (Olivia's sent/inbox)
stmt.run(
  'olivia.hr.manager/' + subject + '.eml',
  'olivia.hr.manager',
  from, to, subject, content,
  'olivia.hr.manager'
);

// Insert recipient copy (Ethan's inbox)
stmt.run(
  'ethan.it.specialist/' + subject + '.eml',
  'ethan.it.specialist',
  from, to, subject, content,
  'ethan.it.specialist'
);

console.log('✅ Email sent successfully!');
console.log();

// Verify both copies
const emails = db.prepare(\"SELECT email_id, from_address, to_address, subject, inbox_owner FROM ob_emails WHERE subject LIKE '%Confirmation: Onboarding%'\").all();
console.log('Verification:', JSON.stringify(emails, null, 2));
"
